package com.northstarbank.console.security;
import com.northstarbank.console.integration.TierClient;import org.springframework.security.authentication.*;import org.springframework.security.core.*;import org.springframework.stereotype.Component;
@Component public class EntitlementsAuthenticationProvider implements AuthenticationProvider{private final TierClient client;public EntitlementsAuthenticationProvider(TierClient c){client=c;}public Authentication authenticate(Authentication a)throws AuthenticationException{try{var x=client.login(a.getName(),String.valueOf(a.getCredentials()));var u=new SessionUser(x.employeeId(),x.email(),x.role(),x.scope(),x.token());return new UsernamePasswordAuthenticationToken(u,null,u.getAuthorities());}catch(Exception e){throw new BadCredentialsException("Invalid credentials");}}public boolean supports(Class<?> c){return UsernamePasswordAuthenticationToken.class.isAssignableFrom(c);}}
